#include <iostream>
#include <thread>

void saludar(int id) {                       // función que correrá en otro hilo
    std::cout << "Hola desde el hilo " << id << '\n';
}

int main() {
    std::thread t1(saludar, 1);               // crea el hilo: ejecuta saludar(1)
    std::thread t2([] { saludar(2); });       // también vale una lambda

    std::cout << "Hola desde main\n";         // main sigue corriendo en paralelo

    t1.join();                                // bloquea main hasta que t1 termine
    t2.join();                                // idem con t2
    return 0;                                 // ya es seguro terminar
}

#include <chrono>
#include <iostream>
#include <thread>

int main() {
    int contador = 0;                         // variable LOCAL de main

    std::thread t([&contador] {               // captura contador por referencia
        std::this_thread::sleep_for(std::chrono::seconds(1));
        contador++;                           // ¡main quizás ya terminó!
    });
    t.detach();                               // ya no lo esperamos

    return 0;                                 // contador se destruye aquí:
}                                             // el hilo usa memoria inválida (UB)

#include <iostream>
#include <thread>

int counter = 0;                              // global: compartida por todos los hilos

void incrementar() {
    for (int i = 0; i < 100000; i++) {
        counter++;                            // leer + sumar + escribir: NO es atómico
    }
}

int main() {
    std::thread t1(incrementar);
    std::thread t2(incrementar);
    t1.join();
    t2.join();
    std::cout << counter << '\n';             // esperado 200000... sale menos casi siempre
}

